<script setup lang="ts">
import {computed,ref} from 'vue'
import {Select,Checkbox,Modal,Table,Input,message} from 'ant-design-vue'
import {useRouter} from 'vue-router'
import StatePanel from '@starbeacon/shared/components/StatePanel.vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import {useModels} from '../models/useModels'
import {checkClass} from '../models/models'
import {blankRequest,stateNames,working,type AnalysisJob} from './analysis'
import {useAnalysis} from './useAnalysis'
import AnalysisDetail from './AnalysisDetail.vue'
const router=useRouter(),models=useModels(),state=useAnalysis('chat'),{conversation,loading,detailError,busy,actionError,unconfirmed,threads,next,pending,error}=state
const ATextarea=Input.TextArea
const question=ref(''),provider=ref(''),hours=ref(24),allowed=ref(false),historyOpen=ref(false),detail=ref<AnalysisJob|null>(null),selectedConversation=ref('')
const providers=computed(()=>models.items.value.filter(p=>p.enabled)),latest=computed(()=>conversation.value?.jobs.at(-1)),blocked=computed(()=>busy.value||!!latest.value&&working(latest.value.state)||!!state.selected.value&&working(state.selected.value.state))
const canSend=computed(()=>!busy.value&&(unconfirmed.value||!blocked.value&&state.available.value&&providers.value.some(p=>p.id===provider.value)&&allowed.value&&!!question.value.trim()))
async function send(){if(!canSend.value)return;let job:AnalysisJob|undefined;if(unconfirmed.value)job=await state.confirm();else{const selected=providers.value.find(p=>p.id===provider.value);if(!selected)return;const r=blankRequest('chat'),end=new Date(Math.floor(Date.now()/60000)*60000);r.provider_id=selected.id;r.provider_revision=selected.revision;r.allow_context=allowed.value;r.question=question.value.trim();r.window={start:new Date(end.getTime()-hours.value*3600000).toISOString(),end:end.toISOString()};r.thread_id=conversation.value?.id??'';r.parent_id=latest.value?.id??'';job=await state.submit(r)}if(job){selectedConversation.value=job.request.thread_id;question.value='';allowed.value=false}}
async function choose(id:string){historyOpen.value=false;state.clear();selectedConversation.value=id;await state.loadThread(id)}
function fresh(){if(blocked.value||unconfirmed.value)return;state.clear();selectedConversation.value='';question.value='';allowed.value=false}
async function cancel(id:string){const job=await state.cancel(id);if(job?.cancel_requested)message.info('取消请求已提交，请以运行结果为准')}
</script>
<template>
 <header class="page-header"><div><h1>智能助手</h1><p class="page-description">依据当前统计解释检测现象并提出调查建议，结论须结合原始证据复核。</p></div><div class="filter-actions"><a-button :disabled="blocked||unconfirmed" @click="fresh">创建对话</a-button><a-button :disabled="busy||unconfirmed" @click="historyOpen=true;state.refresh()">对话记录</a-button></div></header>
 <a-alert v-if="models.error.value" type="error" :message="models.error.value" show-icon class="section-gap"/><a-alert v-if="!models.pending.value&&!providers.length" type="info" message="暂无启用的模型提供方，请先完成模型配置。" show-icon class="section-gap"><template #action><a-button type="link" @click="router.push('/models')">模型配置</a-button></template></a-alert>
 <a-alert v-if="!pending&&!state.available.value&&!error" type="warning" message="模型分析执行服务暂不可用，请联系管理员核对运行状态。" show-icon class="section-gap"/>
 <section class="panel assistant-context"><div class="assistant-fields"><div><label>模型提供方</label><Select v-model:value="provider" aria-label="模型提供方" :disabled="blocked||unconfirmed" placeholder="请选择模型提供方" :options="providers.map(p=>({value:p.id,label:`${p.name} · ${p.model}`}))"/></div><div><label>统计时间范围</label><Select v-model:value="hours" aria-label="统计时间范围" :disabled="blocked||unconfirmed" :options="[{value:24,label:'最近 24 小时'},{value:168,label:'最近 7 天'},{value:720,label:'最近 30 天'}]"/></div></div><p class="muted">本次输入包含所选范围的告警统计、生成时的登记状态和最近对话。统计生成时会固定窗口；原始载荷、PCAP、凭据和设备管理信息不进入模型输入。</p></section>
 <section class="panel assistant-conversation"><StatePanel :loading="loading&&!conversation" :error="!conversation?detailError:''" :empty="false" @retry="selectedConversation&&state.loadThread(selectedConversation)"><template v-if="conversation"><div class="panel-header"><h2>{{conversation.title}}</h2><a-button :loading="loading" @click="state.loadThread(conversation.id)">刷新对话</a-button></div><a-alert v-if="detailError" type="error" :message="`${detailError}。当前显示上次读取的对话。`" show-icon class="section-gap"/><a-button v-if="conversation.next_cursor" :loading="loading" class="section-gap" @click="state.loadThread(conversation.id,conversation.next_cursor)">查看较早对话</a-button><article v-for="job in conversation.jobs" :key="job.id" class="assistant-turn"><p class="assistant-question">{{job.request.question}}</p><div class="assistant-response"><div class="filter-actions"><span :class="['status',checkClass(job.state)]">{{stateNames[job.state]??'其他处理状态'}}</span><span class="muted">{{formatTime(job.created_at)}}</span><a-button type="link" size="small" @click="detail=job">统计与来源</a-button><a-button v-if="working(job.state)" type="link" danger size="small" :disabled="busy||job.cancel_requested" @click="cancel(job.id)">{{job.cancel_requested?'取消请求已提交':'取消分析'}}</a-button></div><template v-if="job.answer"><p>{{job.answer.summary}}</p><div v-for="(item,index) in [...job.answer.observations,...job.answer.recommendations]" :key="index"><p>{{item.text}}</p><small class="muted">来源：{{item.sources.join('、')}}</small></div></template><p v-else class="muted">{{working(job.state)?'分析正在处理，结果将在完成后显示。':job.state==='uncertain'?'请求可能已执行，结果无法确认；不会自动重试。':'尚无可展示的智能结论，可查看统计与运行结果。'}}</p></div></article></template><div v-else class="assistant-empty"><h2>开始调查对话</h2><p class="muted">选择模型与时间范围，输入需要解释的统计现象或调查问题。</p></div></StatePanel></section>
 <section class="panel assistant-composer"><a-alert v-if="actionError" type="error" :message="actionError" show-icon class="section-gap"/><a-alert v-if="unconfirmed" type="warning" message="上次提交结果尚未确认。请确认原请求后继续，避免重复生成和计费。" show-icon class="section-gap"/><ATextarea v-model:value="question" aria-label="调查问题" :maxlength="4000" :rows="3" :disabled="blocked||unconfirmed" placeholder="例如：哪些告警统计需要优先核对，下一步应调查哪些证据？" @keydown.ctrl.enter.prevent="send"/><div class="assistant-send"><Checkbox v-model:checked="allowed" :disabled="blocked||unconfirmed">允许本次调用使用上述统计与对话内容</Checkbox><a-button type="primary" :disabled="!canSend" :loading="busy" @click="send">{{unconfirmed?'确认提交结果':'发送问题'}}</a-button></div><p class="muted">提供方可能按调用计费。关闭页面不会停止已提交的分析，可通过取消分析操作申请终止。</p></section>
 <Modal :open="historyOpen" title="对话记录" :width="760" :footer="null" @cancel="historyOpen=false"><StatePanel :loading="pending&&!threads.length" :error="error" :empty="threads.length===0" description="暂无对话记录。" @retry="state.refresh()"><div class="table-wrap"><Table :data-source="[...threads]" :columns="[{title:'对话主题',dataIndex:'title',width:300},{title:'最后活动',key:'time',width:190},{title:'操作',key:'action',width:90}]" row-key="id" :pagination="false" :scroll="{x:580}"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{formatTime(record.updated_at)}}</template><a-button v-else-if="column.key==='action'" type="link" size="small" @click="choose(record.id)">查看</a-button></template></Table></div><a-button v-if="next" :loading="pending" class="section-gap" @click="state.refresh(next,true)">查看更多对话</a-button></StatePanel></Modal>
 <AnalysisDetail :open="!!detail" :job="detail" :loading="false" error="" :busy="busy" @close="detail=null" @cancel="cancel"/>
</template>
<style scoped>.assistant-context,.assistant-conversation,.assistant-composer{margin-bottom:12px}.assistant-fields{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:12px}.assistant-fields>div{display:grid;gap:4px}.assistant-fields label{font-size:12px;color:var(--muted)}.assistant-empty{min-height:200px;display:grid;align-content:center;justify-items:center;text-align:center;padding:16px}.assistant-turn{display:grid;gap:8px;padding:12px 0;border-top:1px solid var(--line)}.assistant-question{margin:0 0 0 12%;background:#f5f5f5;border:1px solid var(--line);border-radius:8px;padding:12px;white-space:pre-wrap;overflow-wrap:anywhere}.assistant-response p{white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.assistant-response>div+div{margin:8px 0}.assistant-send{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px}.assistant-composer>.muted,.assistant-context>.muted{font-size:12px;margin-bottom:0}@media(max-width:860px){.assistant-fields{grid-template-columns:1fr}.assistant-send{align-items:flex-start;flex-wrap:wrap}.assistant-question{margin-left:0}}</style>
